import {SOILS,SPECIES,CREATURES,freshState,level,condition,overall,meanHealth,advanceDay,water} from './model.js';
import {icon,sceneArt} from './art.js';
let state=freshState(), timer=null, message='', effect='', effectTimer=null;
const $=id=>document.getElementById(id);
const steps=['Add soil','Plant','Add creatures','Environment','Observe & care'];
const announce=text=>{$('announcement').textContent=text;};
function pause(){clearInterval(timer);timer=null;}
function ready(step=state.step){return [!!state.soil,state.plants.some(Boolean),state.creatureChoice,true,true][step];}
function canVisit(step){return step===0 || (step<=state.unlocked && Array.from({length:step},(_,i)=>ready(i)).every(Boolean));}
function effectOnce(type){effect=type;clearTimeout(effectTimer);effectTimer=setTimeout(()=>{effect='';renderScene();},1000);}
function renderScene(){
 $('scene').innerHTML=sceneArt(state,effect)+(state.step===1?[0,1,2].map(i=>`<button class="slot ${state.plants[i]?'occupied':''}" data-slot="${i}" aria-label="${state.plants[i]?'Replace plant':'Plant '+SPECIES[state.selectedPlant].name} in ${['left','center','right'][i]} position">${state.plants[i]?'Replace':'+'}</button>`).join(''):'');
 $('scene-badge').textContent=state.started?`Day ${state.day} · ${overall(state)}`:state.soil?'Growing a little world':'A fresh beginning';
 $('scene-caption').textContent=['Every little world begins with a good foundation.','Find a little place to put down roots.','Even the smallest lives have a part to play.','A little light. A little water. A little balance.','Take your time. See what a little care can do.'][state.step];
 $('scene-readings').innerHTML=state.soil?`<span>SOIL <b>${SOILS[state.soil].name}</b></span><span>MOISTURE <b>${Math.round(state.moisture)}%</b></span><span>LIGHT <b>${level(state.light)}</b></span>`:'<span>One glass jar. Endless little possibilities.</span>';
}
const choice=(id,title,desc,sub,selected,kind)=>`<button class="choice ${selected?'selected':''}" data-${kind}="${id}" aria-pressed="${selected}">${icon(id)}<span class="choice-copy"><strong>${title}</strong><small>${desc}</small>${sub?`<span class="retention">${sub}</span>`:''}</span><span class="radio" aria-hidden="true"></span></button>`;
const range=(id,label,value,desc)=>`<div class="range-group"><label class="range-label" for="${id}">${label}<output id="${id}-value" for="${id}">${level(value)} · ${value}%</output></label><input id="${id}" type="range" min="0" max="100" step="1" value="${value}"><div class="range-ticks"><span>Low</span><span>Moderate</span><span>High</span></div>${desc?`<div class="range-desc">${desc}</div>`:''}</div>`;
const hint=text=>`<div class="hint"><span class="hint-icon" aria-hidden="true">i</span><span>${text}</span></div>`;
function render(focus=false){
 const active=document.activeElement;
 const focusId=active?.id;
 const focusData=active?.tagName==='BUTTON'?Object.entries(active.dataset)[0]:null;
 $('progress').innerHTML=steps.map((name,i)=>`<button class="step ${state.step===i?'active':i<state.unlocked?'done':''}" data-step="${i}" ${canVisit(i)?'':'disabled'} ${state.step===i?'aria-current="step"':''}><span class="number">${i<state.step?'✓':i+1}</span><span>${name}</span></button>`).join('');
 renderScene();
 let content='',title='',desc='';
 if(state.step===0){title='First, a little earth.';desc='A good foundation makes all the difference. Choose a soil for your tiny world.';content=`<div class="choices">${Object.entries(SOILS).map(([id,s])=>choice(id,s.name,s.description,s.retention,state.selectedSoil===id,'soil')).join('')}</div>${hint('Different soils hold water differently. You can change your choice later.')}<button class="primary" id="add-soil">${state.soil?'Update Soil':'Add Soil'}</button>`;}
 if(state.step===1){title='Room for a little green.';desc='Choose a plant, then tap a + inside the jar. Plant up to three little companions.';content=`<div class="choices">${Object.entries(SPECIES).map(([id,s])=>choice(id,s.name,s.detail,`Moisture ${s.moisture.join('–')}% · Light ${s.light.join('–')}%`,state.selectedPlant===id,'plant')).join('')}</div><div class="plants-list">${state.plants.filter(Boolean).length} of 3 planted · Tap an occupied position to replace it.</div><div class="plant-actions">${state.plants.map((p,i)=>p?`<button class="mini" data-remove="${i}" aria-label="Remove ${SPECIES[p.species].name} from ${['left','center','right'][i]} position">Remove ${['left','center','right'][i]} ${SPECIES[p.species].name.toLowerCase()} ×</button>`:'').join('')}</div>`;}
 if(state.step===2){title='Meet the tiny helpers.';desc='Decomposers recycle fallen leaves and decaying matter, keeping this little ecosystem busy.';content=`<div class="choices">${Object.entries(CREATURES).map(([id,c])=>choice(id,c.name,c.description,`Preferred moisture ${c.moisture.join('–')}%`,state.creatures.includes(id),'creature')).join('')}</div>${hint('Choose one, both, or skip. These little helpers respond to moisture, too.')}<button class="secondary" id="skip">Skip for Now</button>`;}
 if(state.step===3){title='Find a gentle balance.';desc=state.started?'Adjust your world, then return to observing. Your day count and plants are kept.':'Set your starting water and light. Watch the glass and earth change as you adjust.';content=range('watering',state.started?'Soil moisture':'Initial watering amount',Math.round(state.moisture),'More water darkens the soil and creates condensation on the glass.')+range('light','Light intensity',state.light,'Brighter light increases evaporation each simulated day.')+hint('Your simulation will start paused. You decide when each new day begins.');}
 if(state.step===4){title='A world of small changes.';desc='Notice, nurture, and let your little world unfold.';content=`<div class="stat-grid"><div class="stat"><span>SOIL MOISTURE</span><strong>${Math.round(state.moisture)}%</strong><small>${level(state.moisture)}</small><div class="meter"><i style="width:${state.moisture}%"></i></div></div><div class="stat"><span>TERRARIUM CONDITION</span><strong>${overall(state)}</strong><div class="meter"><i style="width:${state.creatures.length?(meanHealth(state)+state.creatureHealth)/2:meanHealth(state)}%"></i></div></div></div>${state.plants.map((p,i)=>p?`<div class="plant-condition"><span>${['Left','Center','Right'][i]} · ${SPECIES[p.species].name}</span><span>${condition(p.health)} · ${Math.round(p.health)}%</span></div>`:'').join('')}${state.creatures.length?`<div class="plant-condition"><span>${state.creatures.map(c=>CREATURES[c].name).join(' & ')}</span><span>${condition(state.creatureHealth)} · ${Math.round(state.creatureHealth)}%</span></div>`:''}<div class="daily-note"><strong>${state.day?'DAY '+state.day+' · FIELD NOTE':'BEFORE YOUR FIRST DAY'}</strong>${state.explanation}</div><div class="observe-controls"><button class="primary" id="advance">Advance One Day</button><button class="secondary" id="play" aria-pressed="${!!timer}">${timer?'Pause':'Play automatically'}</button></div><div class="care-row"><button class="secondary water-button" id="water">Add a Little Water</button>${range('care-light','Light',state.light,'')}</div><details class="journal"><summary>Observation journal (${state.history.length} days)</summary><ol>${state.history.map(d=>`<li><strong>Day ${d.day}</strong> · ${Math.round(d.moisture)}% moisture · ${d.light}% light · ${d.condition}<br>${d.explanation}</li>`).join('')||'<li>Your first entry is a day away.</li>'}</ol></details>`;}
 $('controls').className='control-panel'+(state.step===4?' observe':'');
 $('controls').innerHTML=`<div class="status-row"><span class="step-label">${state.step===4?'DAY '+String(state.day).padStart(2,'0')+' / YOUR LIVING JOURNAL':'STEP 0'+(state.step+1)+' / 05'}</span>${state.step===4?`<span class="pause-indicator">${timer?'Playing · 3s / day':'Paused · time is yours'}</span>`:''}</div><h2 tabindex="-1" id="step-heading">${title}</h2><p class="description">${desc}</p>${content}<p class="feedback" role="status">${message||defaultFeedback()}</p><div class="actions">${state.step>0?'<button class="back" id="back">← Back</button>':''}${state.step<4?`<button class="primary grow" id="next" ${ready()?'':'disabled'}>${state.step===3?(state.started?'Return to Observing':'Start Observing'):'Next: '+steps[state.step+1]} <span aria-hidden="true">→</span></button>`:`${state.day>=7?'<button class="text-button" id="view-summary">Seven-day summary ↗</button>':''}<button class="text-button" id="reset" style="margin-left:auto">New terrarium ↗</button>`}</div>`;
 if(focus)$('step-heading').focus({preventScroll:true});
 else if(focusId)$(focusId)?.focus({preventScroll:true});
 else if(focusData)document.querySelector(`[data-${focusData[0]}="${focusData[1]}"]`)?.focus({preventScroll:true});
}
function defaultFeedback(){return [state.soil?`${SOILS[state.soil].name} added. Your foundation is ready.`:'Choose a soil, then add it to your jar.',state.plants.some(Boolean)?'Roots are in. Ready for some tiny helpers?':'Plant at least one green companion to continue.',state.creatureChoice?(state.creatures.length?'Your tiny helpers are settling in.':'A peaceful, plant-only world.'): 'Make a choice or skip to continue.', 'Light and water are set. Your world is ready.', ''][state.step];}
function visit(step){if(!canVisit(step))return;pause();state.step=step;message='';render(true);}
function nextDay(){advanceDay(state);message='';render();announce(`Day ${state.day}. ${state.explanation}`);if(state.day===7&&!state.summarySeen){pause();state.summarySeen=true;render();showSummary();}}
function showSummary(){pause();render();const first=state.history.slice(0,7),last=first.at(-1);const events=state.events.filter(e=>e.day<7);const plants=state.plants.filter(Boolean).map(p=>SPECIES[p.species].name).join(' + ');const low=last?.moisture<40;const high=last?.moisture>75;
 $('summary').innerHTML=`<span class="eyebrow">SEVEN DAYS OF SMALL DISCOVERIES</span><h2>Your little world is growing a story.</h2><p>One week of noticing how soil, light, and care work together.</p><div class="summary-data"><p><strong>Current plant combination</strong><br>${plants}</p><p><strong>First-week environment</strong><br>Moisture: ${state.initialWater}% at start → ${Math.round(last?.moisture||0)}% on day 7.<br>Light ranged from ${Math.min(...first.map(d=>d.light))}% to ${Math.max(...first.map(d=>d.light))}%.</p><p><strong>Your care</strong><br>${events.filter(e=>e.type==='water').length} watering actions · ${events.filter(e=>e.type==='light').length} light changes · ${events.filter(e=>e.type==='soil'||e.type==='plant'||e.type==='moisture').length} setup edits.</p><p><strong>Care suggestion</strong><br>${low?'Watch for dryness and give a little water before moisture leaves your plants’ preferred ranges.':high?'Let the soil dry gradually before adding more water. Check each plant’s upper moisture limit.':'Keep checking your plants’ preferred ranges. Small, regular adjustments can maintain healthy growth.'} ${first.at(-1)?.health<50?'Recovery takes several comfortable days. Give your plants time.':'Keep light within the overlap of your plants’ preferred ranges.'}</p></div><div class="dialog-actions"><button class="primary" id="continue">Continue observing</button><button class="secondary" id="summary-reset">Start a new terrarium</button></div>`;$('summary').showModal();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.close){$(b.dataset.close).close();return;}
 if(b.dataset.step!==undefined){visit(+b.dataset.step);return;}
 if(b.dataset.soil){state.selectedSoil=b.dataset.soil;message='';render();return;}
 if(b.dataset.plant){state.selectedPlant=b.dataset.plant;message=`${SPECIES[state.selectedPlant].name} selected. Tap a position in the jar.`;render();return;}
 if(b.dataset.slot!==undefined){state.plants[+b.dataset.slot]={species:state.selectedPlant,health:90,growth:.85,stressDays:0};if(state.started)state.events.push({day:state.day,type:'plant'});message=`${SPECIES[state.selectedPlant].name} planted. ${state.plants.filter(Boolean).length} of 3 positions filled.`;render();announce(message);return;}
 if(b.dataset.remove!==undefined){state.plants[+b.dataset.remove]=null;message='Plant removed. Choose a plant to fill this spot again.';if(state.started)state.events.push({day:state.day,type:'plant'});render();return;}
 if(b.dataset.creature){const c=b.dataset.creature;state.creatures=state.creatures.includes(c)?state.creatures.filter(x=>x!==c):[...state.creatures,c];state.creatureChoice=state.creatures.length>0;message='';render();return;}
 switch(b.id){case 'add-soil':state.soil=state.selectedSoil;if(state.started)state.events.push({day:state.day,type:'soil'});effectOnce('soil');message=`${SOILS[state.soil].name} added. Your foundation is ready.`;render();break;
 case 'next':if(!ready())return;if(state.step===3&&!state.started){state.started=true;state.initialWater=state.moisture;effectOnce('water');}state.unlocked=Math.max(state.unlocked,state.step+1);visit(state.step+1);break;
 case 'back':visit(state.step-1);break;
 case 'skip':state.creatures=[];state.creatureChoice=true;message='You chose a plant-only world. You can add creatures later.';render();break;
 case 'advance':pause();nextDay();break;
 case 'play':if(timer)pause();else timer=setInterval(nextDay,3000);render();break;
 case 'water':{const amount=water(state);effectOnce('water');message=amount?`Added ${amount.toFixed(0)} moisture points. Plants respond on the next day.`:'The soil is saturated. Wait before adding more water.';render();announce(message);break;}
 case 'guide-button':pause();render();$('guide').showModal();break;
 case 'view-summary':showSummary();break;
 case 'continue':$('summary').close();message='Keep observing at your own pace. The simulation is paused.';render();$('advance').focus();break;
 case 'reset':case 'summary-reset':pause();$('summary').close();render();$('reset-dialog').showModal();break;
 case 'confirm-reset':pause();clearTimeout(effectTimer);effect='';state=freshState();message='';$('reset-dialog').close();render(true);announce('A fresh terrarium is ready. Start by adding soil.');break;
 }
});
document.addEventListener('input',e=>{if(!['watering','light','care-light'].includes(e.target.id))return;const id=e.target.id,value=+e.target.value;
 if(id==='watering'){state.moisture=value;if(!state.started)state.initialWater=value;}else state.light=value;
 $(id+'-value').textContent=`${level(value)} · ${value}%`;renderScene();
});
document.addEventListener('change',e=>{if(!['watering','light','care-light'].includes(e.target.id)||!state.started)return;state.events.push({day:state.day,type:e.target.id==='watering'?'moisture':'light',value:+e.target.value});});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&timer){pause();render();}});
document.querySelectorAll('dialog').forEach(d=>d.addEventListener('close',()=>{if(state.step===4)render();}));
render();
